import React, { useState, useEffect } from 'react';

const BACKEND_URL = 'https://jobmatcher-backend-production.up.railway.app';

export default function JobMatcherApp() {
  const [screen, setScreen] = useState('landing');
    const [loading, setLoading] = useState(false);
      const [adminCode, setAdminCode] = useState(null);

        const [profile, setProfile] = useState({ name: '', email: '', targetRole: '', skills: '', experience: '' });
          const [jobs, setJobs] = useState([]);
            const [newJob, setNewJob] = useState({ title: '', company: '', salary: '', location: '', description: '', contactEmail: '', contactPhone: '' });
              const [searchResults, setSearchResults] = useState([]);

                useEffect(() => {
                    const params = new URLSearchParams(window.location.search);
                        const code = params.get('agency');
                            if (code) {
                                  setAdminCode(code);
                                        setScreen('admin');
                                              const saved = JSON.parse(localStorage.getItem('jobs') || '[]');
                                                    setJobs(saved.filter(j => j.code === code));
                                                        }
                                                          }, []);

                                                            const saveJobs = (updated) => {
                                                                const all = JSON.parse(localStorage.getItem('jobs') || '[]');
                                                                    if (adminCode) {
                                                                          const others = all.filter(j => j.code !== adminCode);
                                                                                localStorage.setItem('jobs', JSON.stringify([...others, ...updated]));
                                                                                    } else {
                                                                                          localStorage.setItem('jobs', JSON.stringify(updated));
                                                                                              }
                                                                                                  setJobs(updated);
                                                                                                    };

                                                                                                      const addJob = (e) => {
                                                                                                          e.preventDefault();
                                                                                                              if (!newJob.title || !newJob.company || !newJob.location) {
                                                                                                                    alert('Fill: Title, Company, Location');
                                                                                                                          return;
                                                                                                                              }
                                                                                                                                  const updated = [...jobs, { ...newJob, id: Date.now(), code: adminCode }];
                                                                                                                                      saveJobs(updated);
                                                                                                                                          setNewJob({ title: '', company: '', salary: '', location: '', description: '', contactEmail: '', contactPhone: '' });
                                                                                                                                              alert('Job added!');
                                                                                                                                                };

                                                                                                                                                  const deleteJob = (id) => {
                                                                                                                                                      saveJobs(jobs.filter(j => j.id !== id));
                                                                                                                                                        };

                                                                                                                                                          const signup = async (e) => {
                                                                                                                                                              e.preventDefault();
                                                                                                                                                                  setLoading(true);
                                                                                                                                                                      try {
                                                                                                                                                                            await fetch(`${BACKEND_URL}/api/auth/signup`, {
                                                                                                                                                                                    method: 'POST',
                                                                                                                                                                                            headers: { 'Content-Type': 'application/json' },
                                                                                                                                                                                                    body: JSON.stringify(profile)
                                                                                                                                                                                                          });
                                                                                                                                                                                                                const users = JSON.parse(localStorage.getItem('users') || '[]');
                                                                                                                                                                                                                      users.push({ name: profile.name, email: profile.email });
                                                                                                                                                                                                                            localStorage.setItem('users', JSON.stringify(users));
                                                                                                                                                                                                                                  setScreen('dashboard');
                                                                                                                                                                                                                                      } catch (e) {
                                                                                                                                                                                                                                            console.log(e);
                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                    setLoading(false);
                                                                                                                                                                                                                                                      };

                                                                                                                                                                                                                                                        const searchJobs = async () => {
                                                                                                                                                                                                                                                            setLoading(true);
                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                      const response = await fetch(`${BACKEND_URL}/api/jobs/search`);
                                                                                                                                                                                                                                                                            const data = await response.json();
                                                                                                                                                                                                                                                                                  setSearchResults([...(data.jobs || []), ...jobs]);
                                                                                                                                                                                                                                                                                      } catch (e) {
                                                                                                                                                                                                                                                                                            setSearchResults(jobs);
                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                    setScreen('results');
                                                                                                                                                                                                                                                                                                        setLoading(false);
                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                            // LANDING PAGE
                                                                                                                                                                                                                                                                                                              if (screen === 'landing') {
                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                        <div style={{ background: 'linear-gradient(135deg, #2563eb, #7c3aed)', minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', textAlign: 'center', padding: '20px' }}>
                                                                                                                                                                                                                                                                                                                                <div>
                                                                                                                                                                                                                                                                                                                                          <h1 style={{ fontSize: '48px', fontWeight: 'bold', marginBottom: '20px' }}>JobMatcher Belfast</h1>
                                                                                                                                                                                                                                                                                                                                                    <p style={{ fontSize: '18px', marginBottom: '30px' }}>Find Your Perfect Job</p>
                                                                                                                                                                                                                                                                                                                                                              <button onClick={() => setScreen('signup')} style={{ background: 'white', color: '#2563eb', padding: '14px 40px', fontSize: '16px', fontWeight: 'bold', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Get Started</button>
                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                    // SIGNUP PAGE
                                                                                                                                                                                                                                                                                                                                                                                      if (screen === 'signup') {
                                                                                                                                                                                                                                                                                                                                                                                          return (
                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ background: 'linear-gradient(135deg, #2563eb, #7c3aed)', minHeight: '100vh', padding: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                                                                                                                                                                                                                                                                                                                                                                        <div style={{ background: 'white', padding: '30px', borderRadius: '8px', maxWidth: '500px', width: '100%' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                  <h1 style={{ fontSize: '28px', fontWeight: 'bold', marginBottom: '20px', color: '#000' }}>Create Profile</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                            <form onSubmit={signup} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                        <input type="text" placeholder="Name" value={profile.name} onChange={(e) => setProfile({...profile, name: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input type="email" placeholder="Email" value={profile.email} onChange={(e) => setProfile({...profile, email: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input type="text" placeholder="Target Role" value={profile.targetRole} onChange={(e) => setProfile({...profile, targetRole: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <textarea placeholder="Skills" value={profile.skills} onChange={(e) => setProfile({...profile, skills: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px', minHeight: '60px' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <select value={profile.experience} onChange={(e) => setProfile({...profile, experience: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <option value="">Experience</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <option value="0-2">0-2 years</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <option value="2-5">2-5 years</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <option value="5-10">5-10 years</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <option value="10+">10+ years</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button type="submit" disabled={loading} style={{ background: '#2563eb', color: 'white', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>{loading ? 'Loading...' : 'Start'}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <button type="button" onClick={() => setScreen('landing')} style={{ background: '#e5e7eb', color: '#000', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Back</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // DASHBOARD PAGE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (screen === 'dashboard') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ minHeight: '100vh', background: '#f3f4f6', padding: '20px', textAlign: 'center' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h1 style={{ fontSize: '28px', fontWeight: 'bold', marginBottom: '30px' }}>Find Jobs</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <button onClick={searchJobs} disabled={loading} style={{ background: '#2563eb', color: 'white', padding: '12px 30px', border: 'none', borderRadius: '6px', cursor: 'pointer', fontSize: '16px' }}>{loading ? 'Searching...' : 'Search Jobs'}</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // RESULTS PAGE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (screen === 'results') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div style={{ minHeight: '100vh', background: '#f3f4f6', padding: '20px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ maxWidth: '800px', margin: '0 auto' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={() => setScreen('dashboard')} style={{ background: '#e5e7eb', padding: '8px 15px', border: 'none', borderRadius: '6px', cursor: 'pointer', marginBottom: '20px' }}>← Back</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h1 style={{ fontSize: '28px', fontWeight: 'bold', marginBottom: '20px' }}>Jobs</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {searchResults.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <p style={{ color: '#6b7280' }}>No jobs</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                searchResults.map(job => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div key={job.id} style={{ background: 'white', padding: '20px', marginBottom: '15px', borderRadius: '8px', borderLeft: '4px solid #2563eb' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <h2 style={{ fontWeight: 'bold', marginBottom: '5px' }}>{job.title}</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p style={{ color: '#666', marginBottom: '10px' }}>{job.company}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <p style={{ marginBottom: '10px' }}>{job.description}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {job.contactEmail && <button onClick={() => window.location.href = `mailto:${job.contactEmail}`} style={{ background: '#2563eb', color: 'white', padding: '8px 16px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Apply</button>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ADMIN PAGE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (screen === 'admin' && adminCode) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div style={{ minHeight: '100vh', background: '#f3f4f6' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div style={{ background: 'white', padding: '20px', borderBottom: '1px solid #ddd' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h1 style={{ fontSize: '24px', fontWeight: 'bold' }}>Post Jobs</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p style={{ color: '#666' }}>{adminCode}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div style={{ maxWidth: '800px', margin: '0 auto', padding: '20px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div style={{ background: 'white', padding: '20px', borderRadius: '8px', marginBottom: '20px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <form onSubmit={addJob} style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <input type="text" placeholder="Title" value={newJob.title} onChange={(e) => setNewJob({...newJob, title: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input type="text" placeholder="Company" value={newJob.company} onChange={(e) => setNewJob({...newJob, company: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <input type="text" placeholder="Location" value={newJob.location} onChange={(e) => setNewJob({...newJob, location: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <input type="text" placeholder="Salary" value={newJob.salary} onChange={(e) => setNewJob({...newJob, salary: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <textarea placeholder="Description" value={newJob.description} onChange={(e) => setNewJob({...newJob, description: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px', minHeight: '80px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <input type="email" placeholder="Contact Email" value={newJob.contactEmail} onChange={(e) => setNewJob({...newJob, contactEmail: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} required />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input type="tel" placeholder="Contact Phone" value={newJob.contactPhone} onChange={(e) => setNewJob({...newJob, contactPhone: e.target.value})} style={{ padding: '10px', border: '1px solid #ddd', borderRadius: '6px' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button type="submit" style={{ background: '#2563eb', color: 'white', padding: '10px', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>Post Job</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </form>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div style={{ background: 'white', padding: '20px', borderRadius: '8px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h2 style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '15px' }}>Jobs ({jobs.length})</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {jobs.length === 0 ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <p style={{ color: '#6b7280' }}>No jobs</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      jobs.map(job => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div key={job.id} style={{ background: '#f9f9f9', padding: '15px', marginBottom: '10px', borderRadius: '6px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h3 style={{ fontWeight: 'bold', margin: 0 }}>{job.title}</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p style={{ fontSize: '13px', color: '#666', margin: 0 }}>{job.company} • {job.location}</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button onClick={() => deleteJob(job.id)} style={{ background: '#ef4444', color: 'white', padding: '5px 10px', border: 'none', borderRadius: '4px', cursor: 'pointer', fontSize: '12px' }}>Delete</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }